const inp=$input.first().json;
const body=(inp && inp.body) ? inp.body : inp;
const chatId=String((body && body.chatId)||'').trim();
const schedule=Array.isArray(body && body.schedule)?body.schedule:[];
const sd=$getWorkflowStaticData('global');
sd.schedules=sd.schedules||{};
if(chatId) sd.schedules[chatId]=schedule;
return [{ json:{ ok:true, chatId, count:schedule.length } }];

const sd=$getWorkflowStaticData('global');
const schedules=sd.schedules||{};
const now=new Date(Date.now()+9*3600*1000);
const hh=now.getUTCHours();
const mm=now.getUTCMinutes();
const out=[];
for(const chatId of Object.keys(schedules)){
  for(const e of (schedules[chatId]||[])){
    if(!e || !e.time) continue;
    const p=String(e.time).split(':'); const eh=parseInt(p[0],10), em=parseInt(p[1],10);
    if(eh===hh && em>=mm && em<mm+5){ out.push({ json:{ chatId, med:e.med||'', when:e.when||'', time:e.time } }); }
  }
}
return out;
